const UAS = [
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
  'Mozilla/5.0 (Macintosh; Intel Mac OS X 14_4) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.4 Safari/605.1.15',
  'Mozilla/5.0 (X11; Linux x86_64; rv:125.0) Gecko/20100101 Firefox/125.0',
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:125.0) Gecko/20100101 Firefox/125.0',
  'Mozilla/5.0 (Linux; Android 14; Pixel 8 Pro) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36'
];
const ua = UAS[Math.floor(Math.random() * UAS.length)];
return [{ json: { userAgent: ua } }];

// ── Sewakost: Regex HTML Parse + Filter + Dedup ──
const staticData = $getWorkflowStaticData('global');
if (!staticData.sentIds) staticData.sentIds = {};

const now = Date.now();
for (const id in staticData.sentIds) {
  if (now - staticData.sentIds[id] > 86400000) delete staticData.sentIds[id];
}

const html = $input.first().json.data || $input.first().json.body || '';
if (!html || html.length < 500) {
  console.log('Sewakost: empty or blocked');
  return [];
}

// ── Try JSON-LD / structured data first ──
const jsonLdMatches = [...html.matchAll(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/g)];
const output = [];

for (const match of jsonLdMatches) {
  try {
    const ld = JSON.parse(match[1]);
    const items = Array.isArray(ld) ? ld : [ld];
    for (const item of items) {
      if (!item['@type'] || !['Product', 'LodgingBusiness', 'Accommodation'].includes(item['@type'])) continue;
      const priceStr = item?.offers?.price || item?.priceRange || '0';
      const price = parseInt(String(priceStr).replace(/\D/g, ''));
      if (!price || price < 300000 || price > 800000) continue;

      const locText = [item.name, item.description, item?.address?.streetAddress,
        item?.address?.addressLocality].filter(Boolean).join(' ').toLowerCase();
      if (!locText.includes('surabaya') && !locText.includes('sby')) continue;

      const imgs = (item.image ? (Array.isArray(item.image) ? item.image : [item.image]) : [])
        .map(i => typeof i === 'string' ? i : i?.url || '').filter(u => u.startsWith('http')).slice(0, 5);
      if (imgs.length === 0) continue;

      const uid = 'sewa_' + (item['@id'] || item.url || item.name || '').replace(/[^a-z0-9]/gi, '_').slice(0, 30);
      if (staticData.sentIds[uid]) continue;
      staticData.sentIds[uid] = now;

      output.push({
        json: {
          source: 'sewakost',
          title: item.name || 'Kos Surabaya',
          price,
          location: [item?.address?.streetAddress, item?.address?.addressLocality].filter(Boolean).join(', ') || 'Surabaya',
          url: item['@id'] || item.url || 'https://sewakost.com/kost/surabaya/',
          description: (item.description || '').slice(0, 500),
          images: imgs,
          scraped_at: new Date().toISOString()
        }
      });
    }
  } catch(e) {}
}

if (output.length > 0) {
  console.log(`Sewakost (JSON-LD): ${output.length} listings`);
  return output;
}

// ── Regex fallback: Sewakost card structure ──
// Cards typically: <div class="kost-item"> or <article class="kost">
const cardBlocks = html.split(/<div[^>]+class="[^"]*(?:kost-item|listing-item|property-item|item-kos)[^"]*"/g).slice(1);

for (let i = 0; i < Math.min(cardBlocks.length, 20); i++) {
  const block = cardBlocks[i].slice(0, 3000); // Each card block

  // Extract URL
  const urlMatch = block.match(/href=["'](https?:\/\/sewakost\.com\/[^"']+|\/kost\/[^"']+)["']/);
  const url = urlMatch ? (urlMatch[1].startsWith('http') ? urlMatch[1] : 'https://sewakost.com' + urlMatch[1]) : null;
  if (!url) continue;

  // Extract price
  const priceMatch = block.match(/Rp[\s.]*([\d]{3}[\d.,]*)/);
  if (!priceMatch) continue;
  const price = parseInt(priceMatch[1].replace(/[.,]/g, ''));
  if (price < 300000 || price > 800000) continue;

  // Location must be Surabaya — verified from page URL
  // (we fetched /kost/surabaya/ so all cards ARE Surabaya)

  // Extract title
  const titleMatch = block.match(/<(?:h[23]|a)[^>]*>\s*([^<]{5,100})\s*<\/(?:h[23]|a)>/);
  const title = titleMatch ? titleMatch[1].trim() : 'Kos Surabaya';

  // Extract images
  const imgs = [...block.matchAll(/(?:data-src|src)=["'](https?:\/\/[^"']+\.(?:jpg|jpeg|webp|png)(?:\?[^"']*)?)["']/g)]
    .map(m => m[1]).filter((u, idx, arr) => arr.indexOf(u) === idx).slice(0, 5);
  if (imgs.length === 0) continue;

  // Dedup
  const uid = 'sewa_' + url.split('/').slice(-3).join('_').replace(/[^a-z0-9_]/gi, '');
  if (staticData.sentIds[uid]) continue;
  staticData.sentIds[uid] = now;

  // Extract address
  const adrMatch = block.match(/(?:alamat|lokasi|jl\.|jalan)[^<]{0,5}<[^>]+>([^<]{5,80})/) ||
    block.match(/<(?:span|p)[^>]*(?:address|location|alamat)[^>]*>([^<]{5,80})/);
  const location = adrMatch ? adrMatch[1].trim() + ', Surabaya' : 'Surabaya';

  output.push({
    json: {
      source: 'sewakost',
      title,
      price,
      location,
      url,
      description: '',
      images: imgs,
      scraped_at: new Date().toISOString()
    }
  });
}

console.log(`Sewakost (regex): ${output.length} listings`);
return output;
